--#1 BACKUP ATM_ACCOUNT
DECLARE @sql NVARCHAR(MAX);
DECLARE @tableName NVARCHAR(128);
DECLARE @tableSchema NVARCHAR(128);
DECLARE @ticketNumber NVARCHAR(128);
DECLARE @backupName NVARCHAR(128);
DECLARE @SUFFIX INT = 0;
DECLARE @BU_DATE CHAR(8);

SET @BU_DATE = CONVERT(CHAR(8), CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Singapore Standard Time' AS DATE), 112);
SET @tableName = @table_name;
SET @tableSchema = 'EDS'
SET @ticketNumber = @ticket;

SET @backupName = @tableName+ '_' + @ticketNumber + '_BU_' + @BU_DATE;

IF EXISTS (
    SELECT 1
    FROM INFORMATION_SCHEMA.TABLES
    WHERE TABLE_NAME = @backupName AND TABLE_SCHEMA = 'D360'
)
BEGIN
    -- Find the highest suffix number
    SELECT TOP 1
        @SUFFIX = TRY_CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS INT)
    FROM INFORMATION_SCHEMA.TABLES
    WHERE
        TABLE_NAME LIKE @backupName + '_%'
        AND TABLE_SCHEMA = 'D360'
        AND ISNUMERIC(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1)) = 1
    ORDER BY TABLE_NAME DESC;

    -- If no _1 exists, make _1. Otherwise, increment.
    SET @SUFFIX = ISNULL(@SUFFIX, 0) + 1;
    SET @backupName = @backupName + '_' + CAST(@SUFFIX AS VARCHAR);
END

SET @sql = '
CREATE TABLE D360.' + QUOTENAME(@backupName) + '
WITH
(
    DISTRIBUTION= ROUND_ROBIN, HEAP
)
AS
SELECT *
FROM '+ @tableSchema+'.' + @tableName + ';';

EXEC sp_executesql @sql;

--#2 Validate Backup
DECLARE @sql NVARCHAR(MAX);
DECLARE @tableName NVARCHAR(128);
DECLARE @tableSchema NVARCHAR(128);
DECLARE @ticketNumber NVARCHAR(128);
DECLARE @backupName NVARCHAR(128);
DECLARE @SUFFIX INT = 0;
DECLARE @BU_DATE CHAR(8);

SET @BU_DATE = CONVERT(CHAR(8), CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Singapore Standard Time' AS DATE), 112);
SET @tableName = @table_name;
SET @tableSchema = 'EDS'
SET @ticketNumber = @ticket;

SET @backupName = @tableName+ '_' + @ticketNumber + '_BU_' + @BU_DATE;

DECLARE @SQLString NVARCHAR(MAX);  
DECLARE @count_tgt NVARCHAR(500);
DECLARE @count_bkp NVARCHAR(500);

SET @SQLString = 'SELECT @count_tgt = count(1)   FROM EDS.'+@tableName ; 
EXECUTE sp_executesql @SQLString;

SET @SQLString = 'SELECT @count_bkp = count(1)   FROM D360.'+QUOTENAME(@backupName) ;  
EXECUTE sp_executesql @SQLString;  
--set @count_bkp=100
IF(@count_tgt<>@count_bkp)
BEGIN

   DECLARE @errmsg1 NVARCHAR(2048) = 'Record count between target table and backup table does not match';

   THROW 50001, @errmsg1, 1;  
END

DECLARE @SQLString NVARCHAR(MAX);


SET @SQLString = 'Delete FROM EDS.'+ @tableName +' WHERE LEFT(RIGHT(FILE_NAME,12),8) >= '+ REPLACE(@PROCESS_DATE,'-',''); 
EXECUTE sp_executesql @SQLString;  

SET @SQLString = 'Update EDS.'+ @tableName +' SET SCD_END_DATE = ''9999-12-31'', ISLATEST =  1 WHERE CONVERT(varchar(12), SCD_END_DATE, 112) >='+ REPLACE(@PREV_PROCESS_DATE,'-',''); 
EXECUTE sp_executesql @SQLString;
